              "BuildKit умеет кэшировать модули и компилятор: RUN --mount=type=cache,target=/go/pkg/mod и target=/root/.cache/go-build. Кэш живёт между сборками, но не попадает в итоговый образ. .dockerignore уменьшает контекст и не даёт утащить .git, .env, локальные бинарники и тестовые данные.",
