          "Когда горутина делает системный вызов, M может блокироваться, и рантайм отдаёт P другому потоку. Сетевые операции Go интегрированы с netpoller: горутина паркуется, а не занимает поток. Поэтому десятки тысяч одновременных соединений дешевле, чем потоки ОС, но каждая горутина всё равно стоит стек и запись в планировщике.",
          "Work stealing выравнивает нагрузку: простаивающий P забирает половину очереди у занятого. Асинхронное вытеснение с Go 1.14 не даёт горутине с долгим циклом монополизировать P. При этом планировщик не гарантирует порядок и не заменяет backpressure."
