          "Оцените числа: QPS, объём данных, размер одного объекта, retention. Например, 10 млн пользователей и 100 млн ссылок — это единицы тысяч QPS на чтение и десятки на запись. Оценки нужны, чтобы выбрать хранилище и кэш, а не для точности.",
          "Нарисуйте высокоуровневые компоненты: клиент, API, сервис, хранилище, кэш, очередь. Затем углубитесь в критический путь. Проговаривайте trade-offs: consistency vs latency, простота vs масштаб, стоимость."
